package com.hmdp.ai.infrastructure.persistence;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.mcp.*;import com.hmdp.ai.shared.id.AiIdGenerator;import com.hmdp.ai.shared.json.ContentHashService;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class JdbcMcpRepositorySqlContractTest {@Test void writesBindEveryPlaceholder(){AtomicInteger statements=new AtomicInteger();JdbcTemplate jdbc=mock(JdbcTemplate.class,inv->{String name=inv.getMethod().getName();if("update".equals(name)&&inv.getArguments().length>0&&inv.getArgument(0)instanceof String){String sql=inv.getArgument(0);Object[]raw=inv.getArguments();Object[]args=raw.length==2&&raw[1]instanceof Object[]?(Object[])raw[1]:Arrays.copyOfRange(raw,1,raw.length);assertThat(args).as(sql).hasSize((int)sql.chars().filter(v->v=='?').count());statements.incrementAndGet();return 1;}if("queryForObject".equals(name))return 0;return org.mockito.Answers.RETURNS_DEFAULTS.answer(inv);});ObjectMapper mapper=new ObjectMapper();JdbcMcpRepository repository=new JdbcMcpRepository(jdbc,mapper,new AiIdGenerator(),new ContentHashService(mapper));McpServer server=new McpServer("server","tenant","workspace","docs","Docs","docs",McpTransport.HTTP,"https://example.com/mcp",null,"[]",1000,false,"UNKNOWN",true,null,"ACTIVE");repository.create(server,"actor");repository.updateHealth("tenant","workspace","server","UP","actor");repository.syncTools(server,Collections.singletonList(new McpToolDescriptor("search","search docs",mapper.createObjectNode().put("type","object"))),"actor");assertThat(statements.get()).isEqualTo(6);}}
